"""Per-scope runtime config accessor.

Each scope gets its own isolated store in `_SCOPES`, keyed by `scope_id`. Reads and writes go
through the accessor so one caller never sees another caller's writes (fix for INC-9923).
"""

_SCOPES = {}           # module-level mapping: scope_id -> {key: value}


def open_scope(scope_id):
    """Open a new scope, creating an isolated store if it doesn't exist."""
    if scope_id not in _SCOPES:
        _SCOPES[scope_id] = {}


def set_value(scope_id, key, value):
    """Write a value into the current scope's isolated store."""
    open_scope(scope_id)           # ensure scope exists
    _SCOPES[scope_id][key] = value


def get_value(scope_id, key):
    """Read a value from the current scope's isolated store."""
    open_scope(scope_id)           # ensure scope exists
    return _SCOPES[scope_id].get(key)


def close_scope(scope_id):
    """Close a scope and optionally clean up its store."""
    if scope_id in _SCOPES:
        del _SCOPES[scope_id]

